function validate([mat]) {
  if (!Array.isArray(mat) || mat.length < 1 || mat.length > 100) return 'mat needs 1 to 100 rows.';
  const cols = Array.isArray(mat[0]) ? mat[0].length : 0;
  if (cols < 1 || cols > 100) return 'mat needs 1 to 100 columns.';
  for (const row of mat) {
    if (!Array.isArray(row) || row.length !== cols) return 'Every row must have the same length.';
    for (let j = 0; j < cols; j++) {
      if (row[j] !== 0 && row[j] !== 1) return 'Every value must be 0 or 1.';
      if (j > 0 && row[j] < row[j - 1]) return 'Each row must be sorted: 0s before 1s.';
    }
  }
  return null;
}

