function adapt(input, solve, kit) {
  const [mat] = input;
  const rows = mat.length;
  const cols = mat[0].length;
  const limit = 1000;
  let calls = 0;
  // The matrix stays inside this closure; the solution can only use get and dimensions.
  const binaryMatrix = Object.freeze({
    get(row, col) {
      calls++;
      if (calls > limit) throw new Error('binaryMatrix.get was called more than 1000 times.');
      if (!Number.isInteger(row) || !Number.isInteger(col) || row < 0 || row >= rows || col < 0 || col >= cols) throw new Error(`get(${row}, ${col}) is outside the ${rows} x ${cols} matrix.`);
      return mat[row][col];
    },
    dimensions() {
      return [rows, cols];
    },
  });
  return solve(binaryMatrix);
}

