function leftMostColumnWithOne(binaryMatrix) {
  const [rows, cols] = binaryMatrix.dimensions();
  let answer = cols;
  for (let row = 0; row < rows; row++) {
    let left = 0;
    let right = answer;
    while (left < right) {
      const mid = Math.floor((left + right) / 2);
      if (binaryMatrix.get(row, mid) === 1) {
        right = mid;
      } else {
        left = mid + 1;
      }
    }
    answer = left;
  }
  return answer === cols ? -1 : answer;
}

