function leftMostColumnWithOne(binaryMatrix) {
  // Staircase walk from the top-right corner: a 1 means look further left, a 0 means this row has nothing better.
  const [rows, cols] = binaryMatrix.dimensions();
  let r = 0;
  let c = cols - 1;
  let found = -1;
  while (r < rows && c >= 0) {
    if (binaryMatrix.get(r, c) === 1) {
      found = c;
      c--;
    } else {
      r++;
    }
  }
  return found;
}

