function generate(rand, size) {
  const rows = size === 'large' ? 90 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 6);
  const cols = size === 'large' ? 90 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 6);
  // Pick the answer first (cols stands for "no 1 at all"), then start every row's 1s at or after it.
  const roll = rand();
  const best = roll < 0.15 ? cols : roll < 0.25 ? 0 : Math.floor(rand() * (cols + 1));
  const starts = Array.from({ length: rows }, () => best + Math.floor(rand() * (cols - best + 1)));
  if (best < cols) starts[Math.floor(rand() * rows)] = best;
  const mat = starts.map(start => Array.from({ length: cols }, (_, col) => (col >= start ? 1 : 0)));
  return [mat];
}
